        log: [
            { emit: 'event', level: 'warn' },
            { emit: 'event', level: 'error' },
        ],
    });

    client.$on('warn', (event) => {
        console.warn(redactPrismaLogEvent('warn', event));
    });
    client.$on('error', (event) => {
