describe('FlightStatusBoard coverage window', () => {
    // The board holds a window rather than the timetable (#153). A search for
    // something outside it returns nothing, which reads as "your flight is
    // missing" unless the board says what it covers.
    it('states the window it was given', () => {
        render(<FlightStatusBoard flights={mockFlights} historyHours={24} horizonDays={7} />);

        expect(
            screen.getByText('Showing departures from the last 24 hours and the next 7 days.')
        ).toBeInTheDocument();
    });

    it('repeats the window when a search finds nothing, and says where to look instead', () => {
        render(<FlightStatusBoard flights={mockFlights} historyHours={24} horizonDays={7} />);

        fireEvent.change(screen.getByPlaceholderText(/Search by flight number/i), {
            target: { value: 'GA999' },
        });

        expect(screen.getByText('🔍 No flights found')).toBeInTheDocument();
        expect(screen.getByText(/next 7 days\. To book a flight further ahead/)).toBeInTheDocument();
    });

    it('reads naturally when the window is a single hour and a single day', () => {
        render(<FlightStatusBoard flights={mockFlights} historyHours={1} horizonDays={1} />);

        expect(
            screen.getByText('Showing departures from the last hour and the next day.')
        ).toBeInTheDocument();
    });

    it('says nothing about a window it was not told about', () => {
        render(<FlightStatusBoard flights={mockFlights} />);

        expect(screen.queryByText(/Showing departures from/)).not.toBeInTheDocument();
    });
});

