const emptyStateMessage = () => {
    const query = searchQuery.trim();
    const status = statusFilter === 'ALL' ? null : getStatusLabel(statusFilter);
    const range = coverage ? ` It only covers departures in ${coverage}.` : '';

    // Both inputs, or the message blames whichever one it checked first. A
