46	        fireEvent.change(screen.getByPlaceholderText('A00000000'), { target: { value: 'US1234567' } });
47	
48	        // Upgrade class to Business (+100%)
49	        const selects = container.querySelectorAll('select');
50	        const classSelect = selects[1]; // index 0 is Gender, index 1 is Cabin Class
51	        fireEvent.change(classSelect, { target: { value: 'BUSINESS' } });
52	
